import type { Question } from '../types'

// ═══════════════════════════════════════════════════════════════
// QUIZ — Développement d'applications réparties (150 questions)
// Chaque fait du cours est couvert ; les erreurs reviennent en boucle.
// ═══════════════════════════════════════════════════════════════

export const dquestions: Question[] = [
  // ───── M1 — Contexte et enjeux ─────
  { id: 'dq1', module: 'd1', q: 'Dans le « cas naïf » (un seul serveur dans le monde), quels sont les résultats constatés ?', options: ['Lenteur, surcharge, risque de panne totale', 'Rapidité, disponibilité, qualité de service', 'Scalabilité infinie, zéro latence', 'Réplication automatique des données'], answer: 0, explain: 'Tous les utilisateurs se connectent à un seul serveur situé en Amérique → lenteur, surcharge, et risque de panne totale si ce serveur tombe.' },
  { id: 'dq2', module: 'd1', q: 'Dans le « cas réel », où sont placés les serveurs ?', options: ['Tous au même endroit, en redondance', 'Répartis géographiquement (Amérique, Europe, Asie, Afrique…), chaque utilisateur se connecte au plus proche', 'Uniquement dans le pays de l\u2019entreprise', 'Sur le poste de chaque utilisateur'], answer: 1, explain: 'Les serveurs sont répartis géographiquement et chaque utilisateur se connecte au serveur le plus proche : rapidité, meilleure disponibilité, tolérance aux pannes, qualité de service.' },
  { id: 'dq3', module: 'd1', q: 'Qu\u2019est-ce qu\u2019une application répartie ?', options: ['Une application installée sur un seul ordinateur puissant', 'Une application dont les composants s\u2019exécutent sur plusieurs ordinateurs reliés par un réseau, coopérant pour fournir un service unique et cohérent', 'Une application qui fonctionne sans réseau', 'Un logiciel de bureau multi-fenêtres'], answer: 1, explain: 'Les composants logiciels s\u2019exécutent sur plusieurs nœuds reliés par un réseau et coopèrent pour fournir un service unique et cohérent — l\u2019utilisateur ne perçoit pas la répartition.' },
  { id: 'dq4', module: 'd1', q: 'Quels composants peuvent faire partie d\u2019une application répartie ?', options: ['Uniquement des programmes', 'Uniquement des bases de données', 'Des programmes, des bases de données, des services web, etc.', 'Uniquement des serveurs web'], answer: 2, explain: 'Les composants peuvent être des programmes, des bases de données, des services web, etc. — géographiquement dispersés mais travaillant comme un tout.' },
  { id: 'dq5', module: 'd1', q: 'Quand un utilisateur publie une photo sur Facebook, que se passe-t-il ?', options: ['Elle reste stockée uniquement sur son téléphone', 'Elle est envoyée à un serveur de stockage, répliquée dans plusieurs centres de données, puis disponible à ses amis via d\u2019autres serveurs', 'Elle est envoyée par email aux amis', 'Elle est stockée sur un seul serveur en Amérique'], answer: 1, explain: 'La photo est envoyée à un serveur de stockage, répliquée dans plusieurs centres de données (sauvegarde + rapidité d\u2019accès) et rendue disponible via d\u2019autres serveurs.' },
  { id: 'dq6', module: 'd1', q: 'Qu\u2019est-ce qu\u2019un système réparti ?', options: ['Un ensemble de machines autonomes reliées par un réseau, coopérant pour offrir l\u2019illusion d\u2019un système unique et cohérent', 'Un seul ordinateur très puissant', 'Un logiciel installé sur plusieurs postes sans communication', 'Un réseau local sans serveur'], answer: 0, explain: 'Machines autonomes + réseau + coopération = illusion d\u2019un système unique et cohérent. Exemple : un cluster de serveurs hébergeant Google.' },
  { id: 'dq7', module: 'd1', q: 'Quel exemple de système réparti est donné dans le cours ?', options: ['Un ordinateur portable', 'Un cluster de serveurs hébergeant un moteur de recherche comme Google', 'Une calculatrice', 'Un disque dur externe'], answer: 1, explain: 'Le cours cite un cluster de serveurs hébergeant un moteur de recherche comme Google.' },
  { id: 'dq8', module: 'd1', q: 'Quelle est la différence entre système réparti et application répartie ?', options: ['Aucune, ce sont des synonymes parfaits', 'Le système réparti est l\u2019infrastructure (réseau, serveurs, protocoles) ; l\u2019application répartie est le logiciel construit au-dessus', 'L\u2019application répartie est plus grande que le système', 'Le système réparti ne fonctionne qu\u2019en local'], answer: 1, explain: 'Système réparti = infrastructure matérielle et logicielle (ex. : Internet). Application répartie = logiciel qui exploite cette infrastructure (ex. : WhatsApp, Netflix, Google Docs).' },
  { id: 'dq9', module: 'd1', q: 'En programmation répartie, comment se fait la communication ?', options: ['Par appels locaux simples et rapides', 'Via le réseau : messages, protocoles, latences', 'Par mémoire partagée uniquement', 'Elle n\u2019existe pas'], answer: 1, explain: 'En programmation répartie, la communication passe par le réseau (messages, protocoles, latences), contrairement aux appels locaux de la programmation classique.' },
  { id: 'dq10', module: 'd1', q: 'Une interface, dans une application répartie, est comparée à…', options: ['Un pare-feu', 'Un contrat qui définit quelles opérations on peut demander et comment les appeler', 'Un câble réseau', 'Une base de données'], answer: 1, explain: 'L\u2019interface est un contrat : quelles opérations (s\u2019authentifier, envoyer un message…) et comment les appeler (HTTP, API REST, message JSON).' },
  { id: 'dq11', module: 'd1', q: 'Quelle caractéristique d\u2019un service Facebook est correcte ?', options: ['Le service d\u2019authentification est hébergé chez l\u2019utilisateur', 'Un service peut être offert par plusieurs serveurs et consommé par plusieurs applications', 'Les services ne communiquent jamais', 'Chaque service a sa propre application visible'], answer: 1, explain: 'Dans un système réparti, un service peut être offert par plusieurs serveurs et consommé par plusieurs applications.' },
  { id: 'dq12', module: 'd1', q: 'Quel événement marque les années 2000 dans l\u2019historique des systèmes répartis ?', options: ['Les premiers réseaux d\u2019ordinateurs', 'L\u2019apparition du cloud computing (AWS, Google Cloud) et des systèmes massivement parallèles', 'L\u2019invention du RPC', 'La blockchain'], answer: 1, explain: 'Années 2000 : cloud computing (Amazon Web Services, Google Cloud) et systèmes massivement parallèles.' },
  { id: 'dq13', module: 'd1', q: 'Que caractérise « aujourd\u2019hui » dans l\u2019évolution des systèmes répartis ?', options: ['Premiers réseaux', 'Émergence de SUN RPC et CORBA', 'IA distribuée, blockchain, edge AI et applications massivement interconnectées', 'Démocratisation d\u2019Internet'], answer: 2, explain: 'Aujourd\u2019hui : intelligence artificielle distribuée, blockchain, edge AI et applications massivement interconnectées.' },

  // ───── M2 — Communication répartie ─────
  { id: 'dq14', module: 'd2', q: 'Qu\u2019est-ce que la communication répartie ?', options: ['L\u2019ensemble des mécanismes, protocoles et modèles permettant à deux entités d\u2019un système distribué d\u2019échanger des données et de coordonner leurs actions malgré la séparation physique', 'La communication entre deux applications sur la même machine', 'Un type de câble réseau', 'Un protocole de chiffrement'], answer: 0, explain: 'C\u2019est l\u2019ensemble des mécanismes, protocoles et modèles permettant aux entités d\u2019échanger et de se coordonner malgré la séparation physique des machines.' },
  { id: 'dq15', module: 'd2', q: 'Quel est l\u2019objectif de la communication répartie ?', options: ['Remplacer le réseau', 'Donner l\u2019illusion que les interactions à distance se déroulent aussi simplement qu\u2019en local, en masquant la complexité du réseau', 'Accélérer le matériel', 'Chiffrer toutes les données'], answer: 1, explain: 'Objectif : illusion d\u2019une interaction aussi simple qu\u2019en local, tout en masquant la complexité du réseau.' },
  { id: 'dq16', module: 'd2', q: 'La communication répartie permet notamment…', options: ['La coopération, le partage de ressources, la coordination des tâches et la transparence', 'Uniquement l\u2019envoi d\u2019emails', 'Uniquement le partage de fichiers', 'La suppression du middleware'], answer: 0, explain: 'Elle permet la coopération entre composants, le partage de ressources, la coordination des tâches et la transparence.' },
  { id: 'dq17', module: 'd2', q: 'Le défi n°1 « hétérogénéité » consiste à…', options: ['Assurer une communication interopérable malgré des nœuds très différents (OS, langages, protocoles variés)', 'Chiffrer les données', 'Augmenter la bande passante', 'Supprimer les IoT'], answer: 0, explain: 'Les nœuds sont très différents (PC, smartphones, serveurs, IoT…) : il faut assurer une communication interopérable malgré ces différences.' },
  { id: 'dq18', module: 'd2', q: 'Le défi de « transparence de la localisation » demande de…', options: ['Publier les IP publiquement', 'Masquer la localisation réelle (IP, port, machine) derrière une abstraction', 'Forcer le client à connaître la position du serveur', 'Déplacer les serveurs'], answer: 1, explain: 'Un composant ne doit pas savoir où se trouve l\u2019autre : la communication doit ressembler à un appel local.' },
  { id: 'dq19', module: 'd2', q: 'Quel exemple illustre la latence perceptible dans une communication répartie ?', options: ['10 ms dans un fichier local', '200 ms de retard dans une visioconférence', '1 seconde pour compiler', '5 minutes de téléchargement'], answer: 1, explain: '200 ms de retard dans une visioconférence sont perceptibles — c\u2019est l\u2019exemple du cours pour la latence.' },
  { id: 'dq20', module: 'd2', q: 'Quel exemple illustre le défi de fiabilité et pannes ?', options: ['Un fichier corrompu', 'En cas de panne réseau, éviter qu\u2019un virement soit débité deux fois', 'Un écran cassé', 'Un mot de passe oublié'], answer: 1, explain: 'Réseaux peu fiables : messages perdus, dupliqués, corrompus, nœuds en panne. Exemple du cours : éviter qu\u2019un virement soit débité deux fois.' },
  { id: 'dq21', module: 'd2', q: 'Le défi « concurrence et synchronisation » est illustré par…', options: ['Deux utilisateurs qui modifient en même temps un même document collaboratif', 'Un utilisateur qui imprime', 'Un serveur qui redémarre', 'Un câble débranché'], answer: 0, explain: 'Plusieurs nœuds peuvent accéder en même temps à la même ressource : gérer les accès concurrents, éviter les conflits, maintenir la cohérence.' },
  { id: 'dq22', module: 'd2', q: 'Le défi « sécurité » exige d\u2019assurer…', options: ['Authentification, confidentialité, intégrité et autorisation', 'Uniquement le chiffrement', 'Uniquement les mots de passe', 'Uniquement la vitesse'], answer: 0, explain: 'La communication sur un réseau ouvert peut être interceptée, modifiée ou usurpée → authentification, confidentialité, intégrité et autorisation.' },
  { id: 'dq23', module: 'd2', q: 'Qu\u2019est-ce que le middleware ?', options: ['Un câble réseau', 'La couche logicielle intermédiaire qui facilite la communication et la transparence entre nœuds (CORBA, Java RMI, …)', 'Un système d\u2019exploitation', 'Une base de données'], answer: 1, explain: 'Le middleware est la couche logicielle intermédiaire facilitant communication et transparence entre nœuds.' },
  { id: 'dq24', module: 'd2', q: 'Un nœud, quel que soit son type, correspond à un bloc logique avec trois fonctions :', options: ['Recevoir, traiter, envoyer des informations', 'Compiler, exécuter, déployer', 'Lire, écrire, supprimer', 'Chiffrer, compresser, stocker'], answer: 0, explain: 'Composition logique d\u2019un nœud : interface d\u2019entrée (recevoir), traitement (décider), interface de sortie (envoyer).' },
  { id: 'dq25', module: 'd2', q: 'Dans la communication synchrone…', options: ['L\u2019émetteur envoie et attend la réponse avant de poursuivre son exécution', 'L\u2019émetteur envoie et continue immédiatement', 'Il n\u2019y a pas de réponse', 'Le récepteur choisit quand répondre'], answer: 0, explain: 'Synchrone : envoi + attente de la réponse (blocage possible). Avantage : simplicité et rapidité de l\u2019échange direct.' },
  { id: 'dq26', module: 'd2', q: 'La limite de la communication asynchrone est…', options: ['La dépendance temporelle forte', 'La complexité plus élevée pour gérer les retours différés', 'Elle bloque l\u2019émetteur', 'Elle est plus lente à établir'], answer: 1, explain: 'Asynchrone : l\u2019émetteur continue sans blocage (avantage : tolérance aux délais) mais gérer les retours différés est plus complexe.' },
  { id: 'dq27', module: 'd2', q: 'Une visioconférence diffusée uniquement aux participants est un exemple de…', options: ['Broadcast', 'Multicast', 'Unicast', 'Anycast'], answer: 1, explain: 'Multicast : un émetteur envoie un message à un groupe spécifique de récepteurs (les participants).' },
  { id: 'dq28', module: 'd2', q: 'Un message envoyé simultanément à tous les abonnés du réseau mobile est un exemple de…', options: ['Unicast', 'Multicast', 'Broadcast', 'Point-à-point'], answer: 2, explain: 'Broadcast : un émetteur diffuse le message à TOUS les nœuds d\u2019un réseau.' },

  // ───── M3 — Modèles de communication ─────
  { id: 'dq29', module: 'd3', q: 'Quels sont les 5 modèles de communication du cours ?', options: ['Message, appels, objets distribués, flux, événements', 'HTTP, FTP, SMTP, DNS, DHCP', 'TCP, UDP, IP, MAC, ARP', 'Client, serveur, pair, bus, cloud'], answer: 0, explain: 'Orientée message, orientée appels, par objets distribués, orientée flux, orientée événements.' },
  { id: 'dq30', module: 'd3', q: 'La communication orientée message est implémentée via…', options: ['Des sockets réseau (TCP ou UDP)', 'Uniquement des websockets', 'Des fichiers', 'Des appels système'], answer: 0, explain: 'Implémentée via des sockets réseau (TCP ou UDP), avec des files de messages (producteur/consommateur) et une adresse de destination.' },
  { id: 'dq31', module: 'd3', q: 'Avantage principal de la communication orientée message ?', options: ['Découplage fort : nœuds en langages différents, sur machines distantes', 'Vitesse maximale garantie', 'Aucune configuration', 'Pas d\u2019adresse nécessaire'], answer: 0, explain: 'Découplage fort — mais complexité de gestion des messages (ordre, duplication, erreurs…).' },
  { id: 'dq32', module: 'd3', q: 'Dans le RPC, quels éléments cachent la complexité réseau ?', options: ['Les stubs (proxy local) qui transforment les appels en messages et les réponses en résultats', 'Les routeurs', 'Les pare-feu', 'Les proxies HTTP'], answer: 0, explain: 'Les stubs transforment les appels en messages et les réponses en résultats : le programmeur n\u2019a pas à gérer l\u2019envoi/réception.' },
  { id: 'dq33', module: 'd3', q: 'Inconvénient du RPC cité dans le cours ?', options: ['Couplage fort : chaque nœud doit connaître la signature de la fonction distante (nom, paramètres, types de retour)', 'Impossible en Java', 'Trop lent pour le web', 'Ne marche qu\u2019en WiFi'], answer: 0, explain: 'Couplage fort (signature obligatoire) + forte dépendance au réseau (défaillances, latence).' },
  { id: 'dq34', module: 'd3', q: 'L\u2019exemple RMI du cours est…', options: ['L\u2019objet Réservation appelle la méthode confirmer() sur l\u2019objet Chambre situé sur un autre nœud', 'Une page web qui appelle un serveur', 'Deux sockets qui s\u2019échangent des octets', 'Un flux vidéo'], answer: 0, explain: 'Système de gestion d\u2019hôtel réparti : l\u2019objet Réservation appelle confirmer() sur l\u2019objet Chambre distant, de manière transparente.' },
  { id: 'dq35', module: 'd3', q: 'Les objets distribués sont implémentés par quels middlewares ?', options: ['Java RMI et CORBA', 'Apache et Nginx', 'Docker et Kubernetes', 'MySQL et Redis'], answer: 0, explain: 'La communication par objets distribués est implémentée par des middlewares comme Java RMI et CORBA.' },
  { id: 'dq36', module: 'd3', q: 'La communication orientée flux convient à…', options: ['Netflix/YouTube (unidirectionnel) et Zoom/Teams (bidirectionnel)', 'Uniquement les emails', 'Uniquement les jeux', 'Uniquement les fichiers'], answer: 0, explain: 'Flux unidirectionnel (diffusion vidéo) ou bidirectionnel (visioconférence) — idéal multimédia, nécessite gestion latence/synchronisation/QoS.' },
  { id: 'dq37', module: 'd3', q: 'Dans l\u2019exemple « commande en ligne », combien de services réagissent à l\u2019événement commande/nouvelle ?', options: ['1', '2', '4 (paiement, logistique, client, fidélité)', 'Aucun'], answer: 2, explain: '4 services abonnés réagissent : paiement (transaction), logistique (emballage/expédition), client (email de confirmation), fidélité (points).' },
  { id: 'dq38', module: 'd3', q: 'Inconvénient de la communication orientée événements ?', options: ['Difficulté à suivre les flux de données ; un même événement peut être reçu par plusieurs services qui réagissent différemment', 'Elle est toujours synchrone', 'Elle ne supporte pas le multicast', 'Elle exige un serveur central'], answer: 0, explain: 'Complexité de gestion : plusieurs récepteurs peuvent réagir différemment au même événement ; difficile de suivre les flux.' },

  // ───── M4 — OSI / TCP-IP ─────
  { id: 'dq39', module: 'd4', q: 'Le modèle OSI a été défini…', options: ['À la fin des années 1970 par l\u2019ISO, en 7 couches', 'En 1995 par Microsoft, en 4 couches', 'En 1983 par l\u2019ANSI, en 5 couches', 'Par DARPA en 4 couches'], answer: 0, explain: 'Modèle théorique défini à la fin des années 1970 par l\u2019ISO (Organisation Internationale de Normalisation) : 7 couches distinctes.' },
  { id: 'dq40', module: 'd4', q: 'Le modèle TCP/IP est…', options: ['Un modèle théorique jamais implémenté', 'Le modèle pratique réellement utilisé, qui simplifie les 7 couches OSI en 4 couches fonctionnelles', 'Identique à l\u2019OSI couche par couche', 'Un modèle à 9 couches'], answer: 1, explain: 'Modèle pratique décrivant l\u2019architecture réellement utilisée : 4 grandes couches fonctionnelles plus faciles à gérer et à coder.' },
  { id: 'dq41', module: 'd4', q: 'Quels protocoles sont cités dans la couche Application de l\u2019OSI ?', options: ['SMTP, HTTP, FTP', 'IP, ARP, ICMP', 'MAC, Ethernet', 'TCP et UDP'], answer: 0, explain: 'SMTP (envoi de mails entre serveurs), HTTP (navigateurs ↔ serveurs Web, requête-réponse), FTP (transfert de fichiers).' },
  { id: 'dq42', module: 'd4', q: 'Les 3 fonctions de la couche Présentation sont…', options: ['Conversion de format, compression, chiffrement', 'Routage, commutation, adressage', 'Ouverture, maintenance, fermeture de session', 'Segmentation, numérotation, retransmission'], answer: 0, explain: 'Présentation : convertir (UTF-8→ASCII, JPEG→BMP), compresser (gain de bande passante), chiffrer/déchiffrer (HTTPS).' },
  { id: 'dq43', module: 'd4', q: 'La couche Session s\u2019occupe de…', options: ['Ouvrir la session, la maintenir active pendant le transfert, puis la fermer proprement', 'Router les paquets', 'Chiffrer les données', 'Convertir les encodages'], answer: 0, explain: 'La session agit comme un canal logique entre les deux appareils : ouverture, maintien (continuité, reprise en cas d\u2019interruption), fermeture.' },
  { id: 'dq44', module: 'd4', q: 'La couche Transport découpe les données en…', options: ['Paquets', 'Segments contenant un en-tête (numéro du segment, numéro du port, …)', 'Trames', 'Bits'], answer: 1, explain: 'Transport : découpage en segments, chaque segment portant un en-tête permettant le réassemblage correct à la réception.' },
  { id: 'dq45', module: 'd4', q: 'Si un paquet dépasse la MTU, que fait la couche réseau ?', options: ['Il est rejeté définitivement', 'Il est fragmenté en plusieurs parties plus petites, puis réassemblé à la réception', 'Il est compressé', 'Il est chiffré'], answer: 1, explain: 'Au-delà de la MTU (Maximum Transmission Unit), le paquet est fragmenté puis réassemblé à la réception.' },
  { id: 'dq46', module: 'd4', q: 'La couche liaison de données utilise quelles adresses ?', options: ['Les adresses IP', 'Les adresses MAC pour identifier émetteur et destinataire sur le réseau local', 'Les noms de domaine', 'Les ports'], answer: 1, explain: 'Liaison de données : paquets → trames, adresses MAC pour l\u2019identification locale, transfert fiable sur le même LAN.' },
  { id: 'dq47', module: 'd4', q: 'La couche Physique convertit les bits en…', options: ['Segments', 'Signaux électriques (câble cuivre), lumineux (fibre optique) ou ondes radio (Wi-Fi, Bluetooth)', 'Paquets IP', 'Sessions'], answer: 1, explain: 'Physique : transmission réelle des bits — signaux électriques (Ethernet cuivre), lumineux (fibre), ondes radio (Wi-Fi/Bluetooth).' },
  { id: 'dq48', module: 'd4', q: 'Les 4 couches du modèle TCP/IP sont…', options: ['Application, Transport, Internet, Accès au réseau', 'Physique, Liaison, Réseau, Session', 'Entrée, Traitement, Sortie, Stockage', 'Web, Mail, DNS, FTP'], answer: 0, explain: 'TCP/IP : 4. Application (HTTP, HTTPS, DNS, SMTP…), 3. Transport (TCP/UDP), 2. Internet (IP), 1. Accès au réseau (MAC, Ethernet, Wi-Fi).' },
  { id: 'dq49', module: 'd4', q: 'Quel est l\u2019ordre correct de l\u2019encapsulation ?', options: ['Message → Segment → Paquet → Trame → Bits', 'Bits → Trame → Paquet → Segment → Message', 'Segment → Message → Trame → Paquet → Bits', 'Paquet → Segment → Message → Bits → Trame'], answer: 0, explain: 'Application produit le message ; Transport ajoute son en-tête → segment ; Internet ajoute IP → paquet ; Accès réseau ajoute MAC → trame → bits.' },
  { id: 'dq50', module: 'd4', q: 'La désencapsulation consiste à…', options: ['Chaque couche lit et retire ses en-têtes pour ne garder que les données destinées à la couche supérieure', 'Compresser les données', 'Chiffrer la trame', 'Fragmenter le paquet'], answer: 0, explain: 'À la réception, chaque couche retire son en-tête avant de passer les données à la couche supérieure.' },

  // ───── M5 — TCP / UDP ─────
  { id: 'dq51', module: 'd5', q: 'Qu\u2019est-ce qu\u2019un protocole en réseau informatique ?', options: ['Un ensemble de règles et de normes définissant comment les nœuds communiquent entre eux', 'Un câble spécifique', 'Un logiciel de navigation', 'Une adresse IP'], answer: 0, explain: 'Protocole = ensemble de règles et de normes définissant comment les nœuds communiquent.' },
  { id: 'dq52', module: 'd5', q: 'TCP est un protocole…', options: ['Non orienté connexion et rapide', 'Orienté connexion : connexion fiable établie avant tout échange, données dans le bon ordre, sans perte ni duplication', 'Sans garantie', 'Uniquement multicast'], answer: 1, explain: 'TCP = orienté connexion, garantit ordre, absence de perte et absence de duplication.' },
  { id: 'dq53', module: 'd5', q: 'Quel est l\u2019ordre correct du 3-way handshake ?', options: ['SYN (client) → SYN-ACK (serveur) → ACK (client)', 'ACK → SYN → FIN', 'SYN → ACK → SYN-ACK', 'GET → 200 OK → close'], answer: 0, explain: '1. Le client envoie SYN (demande de connexion). 2. Le serveur répond SYN-ACK. 3. Le client confirme avec ACK.' },
  { id: 'dq54', module: 'd5', q: 'Que signifient SYN et ACK ?', options: ['Synchronize et Acknowledgement (accusé de réception)', 'Send et Accept', 'Signal et Access', 'Session et Key'], answer: 0, explain: 'SYN = Synchronize (commencer la synchronisation) ; ACK = Acknowledgement (accusé de réception).' },
  { id: 'dq55', module: 'd5', q: 'Pourquoi chaque segment TCP reçoit-il un numéro de séquence ?', options: ['Pour le chiffrer', 'Pour garantir l\u2019ordre d\u2019arrivée', 'Pour le compresser', 'Pour le router'], answer: 1, explain: 'Le numéro de séquence garantit l\u2019ordre d\u2019arrivée ; si un segment est perdu, il est retransmis ; les ACK confirment la réception.' },
  { id: 'dq56', module: 'd5', q: 'Quels sont les avantages de TCP ?', options: ['Transmission fiable, contrôle de flux et de congestion, réassemblage automatique des segments', 'Très rapide, sans surcharge', 'Pas de connexion nécessaire', 'Idéal multicast'], answer: 0, explain: 'TCP : fiable + contrôle de flux/congestion + réassemblage automatique. Inconvénients : lent (contrôles), consomme plus de ressources.' },
  { id: 'dq57', module: 'd5', q: 'Pourquoi TCP est-il critiqué ?', options: ['Il est lent (mécanismes de contrôle et de vérification) et consomme plus de ressources réseau', 'Il perd des données', 'Il ne fonctionne pas sur Internet', 'Il ne supporte pas les emails'], answer: 0, explain: 'Inconvénients TCP : lenteur due aux mécanismes de contrôle/vérification + consommation supérieure de ressources réseau.' },
  { id: 'dq58', module: 'd5', q: 'Quels services reposent sur TCP selon le cours ?', options: ['Messagerie (WhatsApp), Web (HTTP/HTTPS), emails (SMTP/IMAP/POP3), FTP/SFTP, SSH, MySQL/PostgreSQL', 'Uniquement le streaming vidéo', 'DNS uniquement', 'Les jeux en ligne uniquement'], answer: 0, explain: '6 usages TCP : messagerie, navigation web, courrier électronique, transfert de fichiers, accès distant SSH, bases de données distantes.' },
  { id: 'dq59', module: 'd5', q: 'UDP est…', options: ['Orienté connexion', 'Non orienté connexion : datagrammes envoyés sans connexion préalable et sans garantie de livraison', 'Un protocole de couche application', 'Plus fiable que TCP'], answer: 1, explain: 'UDP : non orienté connexion, datagrammes indépendants, aucune garantie d\u2019ordre ni de réception.' },
  { id: 'dq60', module: 'd5', q: 'Si un datagramme UDP est perdu ou arrive en désordre…', options: ['UDP le retransmet automatiquement', 'UDP ne tente pas de le corriger', 'Le routeur le répare', 'TCP prend le relais'], answer: 1, explain: 'UDP ne corrige rien : pas de numérotation, pas d\u2019ACK, pas de retransmission. Erreur détectée → datagramme simplement ignoré.' },
  { id: 'dq61', module: 'd5', q: 'Comment fonctionne le checksum UDP ?', options: ['L\u2019émetteur calcule une valeur de contrôle, la place dans l\u2019en-tête ; le récepteur recalcule : si les valeurs diffèrent → erreur détectée', 'Il chiffre les données', 'Il compresse le datagramme', 'Il numérote les segments'], answer: 0, explain: 'Checksum = valeur calculée depuis le contenu ; placée dans l\u2019en-tête UDP ; recalculée à la réception ; différence → détection d\u2019erreur (calcul facultatif).' },
  { id: 'dq62', module: 'd5', q: 'Quelles applications utilisent UDP selon le cours ?', options: ['Streaming (YouTube, Netflix), jeux en ligne, VoIP (Skype, Zoom), DNS, broadcast/multicast', 'Transfert bancaire', 'SSH', 'Emails'], answer: 0, explain: 'UDP convient au temps réel (streaming, jeux, VoIP), aux requêtes simples (DNS) et à la diffusion broadcast/multicast.' },

  // ───── M6 — Ports & voyage d\u2019une requête ─────
  { id: 'dq63', module: 'd6', q: 'La couche « application » du modèle TCP/IP est…', options: ['La plus basse', 'La plus haute : communication directe entre programmes utilisateurs (navigateur, client mail…)', 'Une couche virtuelle inutile', 'La couche du câble'], answer: 1, explain: 'Couche application = la plus haute du modèle TCP/IP ; elle définit les règles de dialogue entre applications sur deux machines.' },
  { id: 'dq64', module: 'd6', q: 'À quoi sert un numéro de port ?', options: ['À identifier physiquement la carte réseau', 'À diriger les messages vers le bon programme à l\u2019intérieur de l\u2019ordinateur (identifiant logique utilisé par l\u2019OS)', 'À chiffrer les données', 'À router les paquets'], answer: 1, explain: 'Port = identifiant logique (un nombre) utilisé par l\u2019OS pour distinguer les applications qui communiquent sur le réseau.' },
  { id: 'dq65', module: 'd6', q: 'HTTP et HTTPS utilisent respectivement les ports…', options: ['80 et 443', '21 et 22', '25 et 110', '53 et 67'], answer: 0, explain: 'HTTP : port 80 ; HTTPS : port 443 (transfert de pages web).' },
  { id: 'dq66', module: 'd6', q: 'FTP et SMTP utilisent respectivement les ports…', options: ['21 et 25', '80 et 443', '110 et 143', '22 et 23'], answer: 0, explain: 'FTP (transfert de fichiers) : 21 ; SMTP (envoi de mails) : 25.' },
  { id: 'dq67', module: 'd6', q: 'POP3 et IMAP utilisent respectivement les ports…', options: ['110 et 143', '25 et 21', '53 et 80', '161 et 162'], answer: 0, explain: 'POP3 : 110 ; IMAP : 143 — tous deux pour récupérer les mails (réception).' },
  { id: 'dq68', module: 'd6', q: 'Le port du DNS est…', options: ['53', '67-68', '80', '161'], answer: 0, explain: 'DNS (convertir un nom de domaine en adresse IP) : port 53.' },
  { id: 'dq69', module: 'd6', q: 'DHCP utilise les ports…', options: ['67-68', '22-23', '53-54', '110-111'], answer: 0, explain: 'DHCP (donner dynamiquement une IP à un poste) : ports 67-68.' },
  { id: 'dq70', module: 'd6', q: 'SSH et Telnet utilisent respectivement les ports…', options: ['22 et 23', '23 et 22', '21 et 25', '80 et 443'], answer: 0, explain: 'SSH : 22 (avec chiffrement) ; Telnet : 23 (sans chiffrement) — accès distant administrateur.' },
  { id: 'dq71', module: 'd6', q: 'Le port du SNMP est…', options: ['161', '143', '110', '67'], answer: 0, explain: 'SNMP (gérer et surveiller les équipements réseau : routeurs, commutateurs…) : port 161.' },
  { id: 'dq72', module: 'd6', q: 'Dans le schéma illustratif, quelle est l\u2019IP locale du client ?', options: ['192.168.1.10', '10.0.0.5', '102.45.60.10', '165.30.22.5'], answer: 0, explain: 'Client : IP locale 192.168.1.10, MAC AA:AA:AA:AA:AA:AA. Serveur : 10.0.0.5, MAC EE:EE:EE:EE:EE:EE.' },
  { id: 'dq73', module: 'd6', q: 'Dans le schéma, le navigateur traduit l\u2019URL http://www.exemple.com/index.html en…', options: ['GET /index.html HTTP/1.1 + Host: www.exemple.com', 'POST /index.html', 'CONNECT exemple.com', 'PING www.exemple.com'], answer: 0, explain: 'Le navigateur traduit l\u2019URL en requête HTTP : « GET /index.html HTTP/1.1 » avec l\u2019en-tête « Host: www.exemple.com ».' },
  { id: 'dq74', module: 'd6', q: 'À la couche transport dans le schéma, les ports utilisés sont…', options: ['Port source 50500 (éphémère) et port destination 80', 'Port 80 source et 443 destination', 'Port 53 et 25', 'Port 21 et 22'], answer: 0, explain: 'Segment TCP : port source 50500 (ex. éphémère) + port destination 80 (HTTP) + numéro du segment.' },
  { id: 'dq75', module: 'd6', q: 'Le mécanisme NAT consiste à…', options: ['Remplacer l\u2019adresse IP source privée par l\u2019adresse publique du routeur (et inversement au retour)', 'Changer les adresses MAC', 'Chiffrer les paquets', 'Fragmenter les paquets'], answer: 0, explain: 'NAT (Network Address Translation) : le routeur émetteur remplace IP source 192.168.1.10 → 102.45.60.10 (publique) et l\u2019IP destinataire → 165.30.22.5.' },
  { id: 'dq76', module: 'd6', q: 'Au routeur récepteur, la couche Internet fait…', options: ['La NAT inverse : l\u2019IP destination devient 10.0.0.5 (machine du réseau local)', 'Un nouveau NAT vers Internet', 'Le routage vers un autre opérateur', 'Rien du tout'], answer: 0, explain: 'NAT inverse : IP destination redevient l\u2019IP privée du serveur 10.0.0.5.' },
  { id: 'dq77', module: 'd6', q: 'Quand le client envoie la trame, la MAC destination est…', options: ['BB:BB:BB:BB:BB:BB (MAC du routeur émetteur)', 'EE:EE:EE:EE:EE:EE (MAC du serveur)', 'DD:DD:DD:DD:DD:DD', 'Sa propre MAC'], answer: 0, explain: 'La trame va d\u2019abord au routeur : MAC destination = BB:BB:BB:BB:BB:BB ; l\u2019IP destination reste celle du serveur.' },

  // ───── M7 — Sockets ─────
  { id: 'dq78', module: 'd7', q: 'Pourquoi a-t-on besoin des sockets ?', options: ['Ni l\u2019application ni la couche transport ne peuvent communiquer directement : la socket est l\u2019intermédiaire', 'Pour accélérer le CPU', 'Pour remplacer le réseau', 'Pour chiffrer les données'], answer: 0, explain: 'L\u2019application et la couche transport ne communiquent pas directement : la socket est le point d\u2019accès entre les deux.' },
  { id: 'dq79', module: 'd7', q: 'Une socket est définie comme…', options: ['Le couple (adresse IP, port) identifiant une application précise sur une machine', 'Un câble réseau virtuel', 'Un protocole de chiffrement', 'Une adresse MAC'], answer: 0, explain: 'Socket = interface logicielle entre application et transport ; couple (IP, port) = socket endpoint unique sur une machine.' },
  { id: 'dq80', module: 'd7', q: 'Une communication TCP/UDP est identifiée par le quadruplet…', options: ['(IP_client, Port_client, IP_serveur, Port_serveur)', '(MAC, IP, port, protocole)', '(URL, DNS, IP, MAC)', '(SYN, ACK, FIN, RST)'], answer: 0, explain: 'Quadruplet : IP + port du client ET IP + port du serveur.' },
  { id: 'dq81', module: 'd7', q: 'Sans sockets, que se passerait-il ?', options: ['Une application ne pourrait pas accéder au réseau ; les couches basses ne sauraient à quelle application livrer les données ; pas de communication bidirectionnelle simple', 'Internet s\u2019arrêterait définitivement', 'Rien', 'Les données iraient plus vite'], answer: 0, explain: '3 raisons : pas d\u2019accès réseau, livraison à la mauvaise application, pas de moyen simple de communication bidirectionnelle.' },
  { id: 'dq82', module: 'd7', q: 'Dans l\u2019exemple du cours, le port source 53000 est un…', options: ['Port bien connu de HTTP', 'Port éphémère (choisi temporairement par le client)', 'Port du serveur DNS', 'Port réservé au routage'], answer: 1, explain: 'Source Port 53000 = port éphémère ; Destination Port 80 = HTTP, sur l\u2019IP 142.250.185.78.' },
  { id: 'dq83', module: 'd7', q: 'À l\u2019étape 4 du principe de base des sockets…', options: ['La couche transport du destinataire reçoit le paquet et le redirige vers la socket identifiée par le port', 'Le client ferme la connexion', 'Le DNS résout le nom', 'Le routeur applique le NAT'], answer: 0, explain: 'Étape 4 : le transport du destinataire redirige le paquet vers la socket identifiée par le port ; étape 5 : l\u2019application lit les données depuis sa socket.' },
  { id: 'dq84', module: 'd7', q: 'Les données TCP circulent sous forme de…', options: ['Datagrammes indépendants', 'Flux continus garantissant livraison sans perte, ordre et fiabilité', 'Trames MAC', 'Fichiers'], answer: 1, explain: 'TCP = orienté connexion, flux continus : livraison sans perte, respect de l\u2019ordre, fiabilité.' },
  { id: 'dq85', module: 'd7', q: 'Quelle classe Java écoute les connexions entrantes côté serveur TCP ?', options: ['Socket', 'ServerSocket', 'DatagramSocket', 'NetworkChannel'], answer: 1, explain: 'ServerSocket : côté serveur, écoute les connexions entrantes sur un port donné. Socket : côté client (et serveur après acceptation).' },
  { id: 'dq86', module: 'd7', q: 'Après acceptation d\u2019une connexion TCP, l\u2019échange se fait via…', options: ['Des flux (InputStream et OutputStream)', 'Des datagrammes', 'Des trames', 'Des websockets'], answer: 0, explain: 'Une fois la connexion acceptée, les deux programmes échangent via les flux InputStream/OutputStream.' },
  { id: 'dq87', module: 'd7', q: 'Dans le diagramme TCP du cours, la séquence serveur « Open Listen » est…', options: ['socket → bind → listen', 'bind → socket → connect', 'listen → accept → close', 'connect → write → read'], answer: 0, explain: 'Serveur : socket → bind → listen (Open Listen) puis accept reçoit la connection request du connect client.' },
  { id: 'dq88', module: 'd7', q: 'Dans le diagramme TCP, quand le client fait « close » (End Of File)…', options: ['Le serveur lit (read) puis ferme (close), et revient sur accept', 'Tout s\u2019arrête définitivement', 'Le client redémarre', 'Le NAT s\u2019active'], answer: 0, explain: 'End Of File : client close → serveur read → serveur close → le serveur revient sur accept (boucle de service).' },
  { id: 'dq89', module: 'd7', q: 'Quelles classes Java sont utilisées pour les sockets UDP ?', options: ['Socket et ServerSocket', 'DatagramSocket et DatagramPacket', 'InputStream et OutputStream', 'URLConnection'], answer: 1, explain: 'DatagramSocket = la « prise » de communication (envoyer/recevoir) ; DatagramPacket = le paquet (données + IP destinataire + port).' },
  { id: 'dq90', module: 'd7', q: 'En UDP, chaque message envoyé est…', options: ['Lié au précédent par une session', 'Indépendant des autres : aucune session ni connexion persistante', 'Numéroté et retransmis', 'Chiffré par défaut'], answer: 1, explain: 'UDP : datagrammes indépendants, pas de session ni connexion persistante ; le serveur peut répondre via un autre datagramme.' },
  { id: 'dq91', module: 'd7', q: 'Dans le diagramme UDP du cours, la séquence serveur est…', options: ['Create a socket → Bind the socket → Receive request → Send response', 'Socket → connect → write → close', 'Bind → listen → accept', 'Send → Receive → Close'], answer: 0, explain: 'Serveur UDP : create → bind → receive request → send response. Client : create → bind → send request → receive response.' },

  // ───── M8 — Bas vs haut niveau ─────
  { id: 'dq92', module: 'd8', q: 'Avec les sockets, que doit gérer le programmeur ?', options: ['La création de la connexion (IP, port), l\u2019envoi/réception de flux d\u2019octets, le format des messages (encodage, protocole applicatif)', 'Uniquement l\u2019interface graphique', 'Rien, tout est automatique', 'Uniquement le DNS'], answer: 0, explain: 'Bas niveau : le programmeur gère connexion, flux d\u2019octets et format des messages. Avantage : contrôle total, performance.' },
  { id: 'dq93', module: 'd8', q: 'Quels objectifs ont motivé les mécanismes haut niveau ?', options: ['Simplifier la programmation réseau, automatiser les échanges (marshalling, transport, erreurs), communication transparente, interopérabilité', 'Supprimer le réseau', 'Augmenter la complexité du code', 'Remplacer TCP'], answer: 0, explain: '4 objectifs : simplifier, automatiser, rendre transparent (comme un appel local), assurer l\u2019interopérabilité entre systèmes et langages.' },
  { id: 'dq94', module: 'd8', q: 'L\u2019unité d\u2019échange en bas niveau (sockets) est…', options: ['Un flux d\u2019octets', 'Un appel de fonction/méthode/service', 'Un objet Java', 'Un événement'], answer: 0, explain: 'Bas niveau : flux d\u2019octets. Haut niveau : appel de fonction/méthode/service.' },
  { id: 'dq95', module: 'd8', q: 'En haut niveau, le format des données est…', options: ['Défini par le programmeur', 'Structuré (JSON, XML, Protobuf...)', 'Toujours binaire brut', 'Toujours du texte'], answer: 1, explain: 'Haut niveau : format structuré (JSON, XML, Protobuf…) ; bas niveau : défini par le programmeur.' },
  { id: 'dq96', module: 'd8', q: 'Quel mécanisme domine les années 1980 dans l\u2019historique du cours ?', options: ['RPC (Sun RPC, ONC RPC)', 'GraphQL', 'REST', 'WebSockets'], answer: 0, explain: 'Milieu-fin des années 1980 : RPC — première abstraction haut niveau (appel de procédure distante, sérialisation automatique).' },
  { id: 'dq97', module: 'd8', q: 'Quels mécanismes apparaissent dans les années 1990 ?', options: ['CORBA, Java RMI, DCOM', 'SOAP et XML-RPC', 'REST et gRPC', 'GraphQL et WebSockets'], answer: 0, explain: 'Années 1990 : extension du RPC aux objets distants — CORBA, Java RMI, DCOM (références d\u2019objets, exceptions à distance).' },
  { id: 'dq98', module: 'd8', q: 'Les années 2010 sont dominées par…', options: ['REST, JSON-RPC, gRPC, Thrift', 'Sockets', 'CORBA', 'SOAP/WSDL'], answer: 0, explain: 'Années 2010 : HTTP + JSON (REST) ou binaire (gRPC, Thrift) — APIs simples, typées, performantes, adaptées microservices et cloud.' },
  { id: 'dq99', module: 'd8', q: 'Les années 2020+ voient arriver…', options: ['GraphQL, WebSockets, Async APIs (streaming, bidirectionnel, performance, résilience)', 'Uniquement des sockets', 'CORBA', 'DCE RPC'], answer: 0, explain: '2020+ : environnements cloud/mobiles/temps réel — GraphQL, WebSockets, Async APIs : communication flexible, streaming, bidirectionnelle.' },
  { id: 'dq100', module: 'd8', q: 'Quelles sont les 4 grandes familles de mécanismes haut niveau ?', options: ['RPC, RMI, Services Web (SOAP, REST, gRPC), mécanismes orientés message (JMS, RabbitMQ, Kafka)', 'TCP, UDP, IP, ICMP', 'OSI, TCP/IP, DNS, DHCP', 'Client, serveur, pair, bus'], answer: 0, explain: 'RPC (fonction distante), RMI (extension objet), Services Web, orientés message (asynchrone, brokers).' },

  // ───── M9 — RPC ─────
  { id: 'dq101', module: 'd9', q: 'L\u2019objectif du RPC est…', options: ['Masquer la complexité du réseau et rendre la programmation distribuée plus proche de la programmation locale', 'Accélérer le processeur', 'Chiffrer les communications', 'Remplacer les bases de données'], answer: 0, explain: 'RPC : appeler une procédure située sur une autre machine comme si elle était locale.' },
  { id: 'dq102', module: 'd9', q: 'Qu\u2019est-ce que l\u2019IDL ?', options: ['Un fichier qui décrit les fonctions accessibles à distance (noms, paramètres, types de retour)', 'Un compilateur Java', 'Un protocole de transport', 'Un annuaire de services'], answer: 0, explain: 'IDL (Interface Definition Language) : description des fonctions distantes — écrit par le développeur du service (serveur).' },
  { id: 'dq103', module: 'd9', q: 'Le stub client (proxy) fait quoi ?', options: ['Code généré côté client qui remplace l\u2019appel réel et s\u2019occupe du marshalling + envoi', 'Il exécute la fonction réelle', 'Il stocke les données', 'Il route les paquets'], answer: 0, explain: 'Stub client = proxy généré côté client : marshalling + envoi. Le skeleton (côté serveur) reçoit, fait l\u2019unmarshalling et appelle la procédure réelle.' },
  { id: 'dq104', module: 'd9', q: 'Le marshalling est…', options: ['La conversion des paramètres en représentation binaire (Protobuf, Thrift) ou textuelle (JSON, XML) pour transport', 'La suppression des données', 'Le chiffrement TLS', 'La compression d\u2019images'], answer: 0, explain: 'Marshalling = sérialisation pour transport ; unmarshalling = désérialisation (reconstitution des paramètres à l\u2019autre bout).' },
  { id: 'dq105', module: 'd9', q: 'Le RPC runtime est…', options: ['Une couche logicielle interne fournie par la bibliothèque RPC : envoie les messages via le réseau (souvent sockets TCP/UDP), gère transmission, attente et réception', 'Un serveur web', 'Un IDE', 'Un format de fichier'], answer: 0, explain: 'RPC runtime = mécanisme sous-jacent de communication de la bibliothèque RPC.' },
  { id: 'dq106', module: 'd9', q: 'Quel est l\u2019ordre des 6 phases du fonctionnement RPC ?', options: ['Définition de l\u2019interface → Génération du code → Exécution côté serveur → Appel côté client → Traitement côté serveur → Retour côté client', 'Appel client → définition IDL → génération → retour', 'Génération → IDL → appel → exécution', 'Exécution → appel → IDL → retour'], answer: 0, explain: '6 phases : IDL, génération stubs/squelettes, serveur implémente + enregistre, appel client (marshalling), traitement serveur (unmarshalling + appel réel), retour client.' },
  { id: 'dq107', module: 'd9', q: 'Quel outil génère le code pour ONC RPC (Sun RPC) ?', options: ['rpcgen', 'MIDL', 'idltojava', 'protoc'], answer: 0, explain: 'ONC RPC → rpcgen ; DCE RPC → compilateur idl ; CORBA → idl compiler (idltojava, omniidl) ; Microsoft RPC → MIDL.' },
  { id: 'dq108', module: 'd9', q: 'Quel outil correspond à Microsoft RPC (Windows) ?', options: ['MIDL (Microsoft IDL Compiler)', 'rpcgen', 'omniidl', 'rmic'], answer: 0, explain: 'Microsoft RPC utilise MIDL (Microsoft IDL Compiler).' },
  { id: 'dq109', module: 'd9', q: 'Dans le web moderne (SOAP, REST, gRPC), comment le client découvre-t-il le service ?', options: ['Une description publique (WSDL ou .proto) que le client télécharge pour générer son stub automatiquement', 'Il devine', 'Le serveur appelle le client', 'Par SMS'], answer: 0, explain: 'Web moderne : description publique (WSDL, .proto) téléchargée pour générer le stub. Environnement distribué : annuaire (naming service). Même entreprise : IDL/interface Java documentée.' },
  { id: 'dq110', module: 'd9', q: 'Dans le pseudocode du cours, à quoi ressemble une requête RPC ?', options: ['{"method":"add","args":[3,4]}', '<add>3+4</add>', 'add(3,4) en binaire brut', 'GET /add?a=3&b=4'], answer: 0, explain: 'Le skeleton parse le JSON : {"method":"add","args":[3,4]} → impl.add(3,4) → réponse {"result": 7}.' },
  { id: 'dq111', module: 'd9', q: '« En coulisse », quelle est la bonne séquence ?', options: ['stub.marshall(3,4) → transport.send → skeleton.unmarshall → server.add(3,4)=7 → server.marshall(7) → client.unmarshall → 7', 'server.add → marshall → transport → done', 'unmarshall → send → marshall → add', 'transport → dns → marshall'], answer: 0, explain: '5 étapes en coulisse : marshall client → send → receive+unmarshall+exécution serveur → marshall(7)+send → receive+unmarshall client → 7.' },
  { id: 'dq112', module: 'd9', q: 'Parmi les avantages du RPC…', options: ['IDL + génération de code : cohérence des interfaces, moins d\u2019erreurs manuelles', 'Il supprime la latence', 'Il garantit exactly-once', 'Il est toujours plus rapide que les sockets'], answer: 0, explain: 'Avantages : facilité de développement, encapsulation de la communication, IDL+génération (cohérence), paradigmes variés, interopérabilité.' },
  { id: 'dq113', module: 'd9', q: 'L\u2019inconvénient « fausse impression de transparence » signifie…', options: ['Un appel distant n\u2019est pas un appel local — latence, pannes, variabilité', 'Le code est illisible', 'Les données disparaissent', 'Le réseau s\u2019arrête'], answer: 0, explain: 'Fausse transparence : le développeur oublie que l\u2019appel traverse le réseau (latence, pannes, variabilité).' },
  { id: 'dq114', module: 'd9', q: 'Pourquoi la scalabilité peut-elle souffrir avec RPC ?', options: ['Un nombre élevé d\u2019appels RPC synchrones peut créer des goulots d\u2019étranglement', 'Le réseau disparaît', 'Les objets ne se sérialisent pas', 'L\u2019IDL limite le nombre de fonctions'], answer: 0, explain: 'Les appels synchrones en grand nombre créent des goulots d\u2019étranglement.' },

  // ───── M10 — CORBA / RMI ─────
  { id: 'dq115', module: 'd10', q: 'Dans les années 1980, les langages dominants (C, Pascal, Ada) étaient…', options: ['Procéduraux : on appelait à distance des fonctions, pas des objets', 'Orientés objet', 'Fonctionnels', 'Des langages web'], answer: 0, explain: 'RPC appelait des fonctions/procédures. La POO s\u2019impose fin années 1980 / début 1990 (C++, Smalltalk, puis Java).' },
  { id: 'dq116', module: 'd10', q: 'Qui a conçu CORBA et quand ?', options: ['L\u2019OMG (Object Management Group), début des années 1990, avant que Java n\u2019existe (1995)', 'Sun Microsystems en 1995', 'Microsoft en 1991', 'L\u2019ISO en 1979'], answer: 0, explain: 'CORBA = Common Object Request Broker Architecture, conçue par l\u2019OMG au début des années 1990.' },
  { id: 'dq117', module: 'd10', q: 'L\u2019objectif de CORBA est…', options: ['Permettre à des programmes écrits dans différents langages (C++, etc.) de communiquer en appelant des méthodes d\u2019objets distants de manière transparente', 'Uniquement la communication Java-Java', 'Remplacer HTTP', 'Chiffrer les emails'], answer: 0, explain: 'CORBA = extension orientée objet du RPC visant l\u2019interopérabilité multi-langages.' },
  { id: 'dq118', module: 'd10', q: 'Quel est le rôle de l\u2019ORB dans CORBA ?', options: ['Il transporte la requête au serveur et gère la communication réseau — même rôle que le RPC runtime', 'Il compile l\u2019IDL', 'Il remplace le DNS', 'Il génère les données'], answer: 0, explain: 'ORB (Object Request Broker) = l\u2019intermédiaire qui s\u2019occupe de toute la mécanique réseau entre client et serveur.' },
  { id: 'dq119', module: 'd10', q: 'Quelles sont les limites de CORBA ?', options: ['Complexe à configurer, beaucoup de fichiers et de couches pour de simples appels', 'Il est spécifique à Java', 'Il ne supporte pas les objets', 'Il est trop rapide'], answer: 0, explain: 'Malgré son succès dans les années 1990 : complexité de configuration et nombreux fichiers/couches.' },
  { id: 'dq120', module: 'd10', q: 'Les ingénieurs de Sun ont voulu un système RMI…', options: ['Plus léger, spécifique à Java, utilisant la sérialisation native des objets Java', 'Multi-langages comme CORBA', 'Basé sur XML', 'Sans JVM'], answer: 0, explain: 'RMI : inspiré de CORBA mais plus léger, spécifique Java, sérialisation native.' },
  { id: 'dq121', module: 'd10', q: 'La définition exacte de RMI est…', options: ['Un mécanisme purement Java, inspiré de CORBA, qui permet d\u2019invoquer une méthode sur un objet situé sur une autre machine Java, comme si l\u2019objet était local', 'Un protocole de transport', 'Un langage d\u2019interface multi-langages', 'Une base de données répartie'], answer: 0, explain: 'RMI = Remote Method Invocation : invocation de méthodes sur des objets Java distants comme s\u2019ils étaient locaux.' },
  { id: 'dq122', module: 'd10', q: 'Que doit faire l\u2019interface distante RMI ?', options: ['Étendre java.rmi.Remote et déclarer toutes ses méthodes avec throws RemoteException', 'Étendre UnicastRemoteObject', 'Implémenter Serializable', 'Étendre Thread'], answer: 0, explain: 'Interface distante : extends Remote (marqueur) + throws RemoteException sur chaque méthode.' },
  { id: 'dq123', module: 'd10', q: 'La classe d\u2019implémentation RMI doit…', options: ['Implémenter l\u2019interface distante, hériter de UnicastRemoteObject, fournir le code concret des méthodes', 'Étendre Thread', 'Être final', 'Résider chez le client'], answer: 0, explain: 'HelloImpl extends UnicastRemoteObject implements Hello — le constructeur peut lever RemoteException (super()).' },
  { id: 'dq124', module: 'd10', q: 'Dans le serveur RMI, quelle méthode démarre le registre sur le port 1099 ?', options: ['LocateRegistry.createRegistry(1099)', 'Registry.start(1099)', 'Naming.start(1099)', 'Remote.bind(1099)'], answer: 0, explain: 'LocateRegistry.createRegistry(1099) démarre le registre ; puis Naming.rebind("rmi://localhost/HelloService", obj) enregistre l\u2019objet.' },
  { id: 'dq125', module: 'd10', q: 'Comment le client RMI obtient-il la référence distante ?', options: ['Hello obj = (Hello) Naming.lookup("rmi://localhost/HelloService")', 'new HelloImpl()', 'Socket(1099)', 'Remote.get()'], answer: 0, explain: 'Naming.lookup localise l\u2019objet via le registre et retourne le stub ; le client appelle ensuite obj.direBonjour("Mouna") comme un appel local.' },
  { id: 'dq126', module: 'd10', q: 'La commande rmiregistry…', options: ['Écoute par défaut sur le port 1099 et doit être lancée dans le même répertoire que les classes compilées', 'Écoute sur le port 80', 'Doit être lancée avant javac', 'N\u2019existe plus'], answer: 0, explain: 'rmiregistry : port par défaut 1099, lancé dans un terminal séparé, dans le répertoire des classes compilées.' },
  { id: 'dq127', module: 'd10', q: 'Quel est l\u2019ordre correct d\u2019exécution RMI du cours ?', options: ['javac *.java → rmiregistry → java ServeurRMI → java ClientRMI', 'rmiregistry → javac → client → serveur', 'java ClientRMI → java ServeurRMI → javac', 'javac → java ServeurRMI → rmiregistry → java ClientRMI'], answer: 0, explain: '1. javac *.java ; 2. rmiregistry ; 3. java ServeurRMI (« Serveur RMI prêt... ») ; 4. java ClientRMI (« Réponse du serveur : Bonjour, Mouna ! »).' },
  { id: 'dq128', module: 'd10', q: 'Dans l\u2019architecture RMI, que fait l\u2019étape (3) « Return Client Stub » ?', options: ['Le registre renvoie le stub client au programme client après son lookup', 'Le serveur renvoie les données', 'Le client renvoie son objet', 'Le skeleton se copie'], answer: 0, explain: 'Séquence : (1) Register server object → (2) Look for server object → (3) Return Client Stub → (4) Data Communication entre stub et skeleton.' },
  { id: 'dq129', module: 'd10', q: 'Depuis quelle version de Java le skeleton RMI est-il créé dynamiquement ?', options: ['Java 5', 'Java 1.2', 'Java 8', 'Java 11'], answer: 0, explain: 'Depuis Java 5, le skeleton est créé dynamiquement — plus besoin de compilation manuelle via RMIC.' },
  { id: 'dq130', module: 'd10', q: 'Dans le tableau RPC vs RMI, l\u2019outil de génération de RMI est…', options: ['rmic', 'rpcgen', 'idlj', 'MIDL'], answer: 0, explain: 'RMI → rmic ; RPC → idlj, protoc, etc. (selon la technologie).' },
  { id: 'dq131', module: 'd10', q: 'En RMI, les données transmises sont…', options: ['Des objets Java (via sérialisation)', 'Des types simples uniquement', 'Du XML', 'Des flux d\u2019octets bruts'], answer: 0, explain: 'RMI transmet des objets Java complets via sérialisation ; RPC transmet des types simples (int, string…).' },
  { id: 'dq132', module: 'd10', q: 'L\u2019inconvénient majeur de RMI est…', options: ['Spécifique à Java : dépendance forte à la JVM, peu adapté aux systèmes hétérogènes', 'Il est trop lent', 'Il ne masque pas le réseau', 'Il ne passe pas d\u2019objets'], answer: 0, explain: 'RMI : simple, objets complets, réseau masqué, intégré à Java — mais non interopérable (JVM uniquement).' },

  // ───── M11 — Architectures fondations ─────
  { id: 'dq133', module: 'd11', q: 'L\u2019architecture d\u2019une application répartie décrit…', options: ['Où sont placés les composants, comment ils communiquent, comment ils coopèrent', 'Uniquement le choix du langage', 'La couleur de l\u2019interface', 'Le prix des serveurs'], answer: 0, explain: '3 questions : où ? comment communiquent-ils ? comment coopèrent-ils ? — plan d\u2019organisation sur plusieurs ordinateurs.' },
  { id: 'dq134', module: 'd11', q: 'L\u2019architecture centralisée (années 1960) se caractérise par…', options: ['Un seul ordinateur puissant partagé par plusieurs utilisateurs', 'Des microservices', 'Un réseau P2P', 'Le serverless'], answer: 0, explain: '1960 : centralisée ; 1980 : client-serveur ; 1990 : multi-couches (CORBA) ; 2000 : SOA ; 2010+ : microservices, événementielle, serverless.' },
  { id: 'dq135', module: 'd11', q: 'La scalabilité est…', options: ['La capacité à augmenter efficacement ses ressources pour supporter une charge plus élevée sans dégradation notable des performances', 'La vitesse de réponse', 'La capacité à rester allumé', 'La facilité de correction'], answer: 0, explain: 'Scalabilité = montée en charge sans dégradation notable.' },
  { id: 'dq136', module: 'd11', q: 'La tolérance aux pannes est…', options: ['L\u2019aptitude à continuer de fonctionner malgré la défaillance de l\u2019un de ses composants', 'La capacité à éviter toute panne', 'La rapidité de redémarrage', 'La redondance des câbles'], answer: 0, explain: 'Tolérance aux pannes : continuer malgré la défaillance d\u2019un composant.' },
  { id: 'dq137', module: 'd11', q: 'La transparence vise à…', options: ['Masquer la complexité et la distribution du système pour un fonctionnement perçu comme homogène et simple', 'Afficher les IP aux utilisateurs', 'Rendre le code visible', 'Chiffrer l\u2019écran'], answer: 0, explain: 'Transparence : l\u2019utilisateur/programmeur perçoit un fonctionnement homogène et simple.' },
  { id: 'dq138', module: 'd11', q: 'Le faible couplage signifie…', options: ['Les composants interagissent avec un minimum de dépendances, permettant une évolution indépendante des modules', 'Les composants sont soudés', 'Le réseau est lent', 'Le code est dupliqué'], answer: 0, explain: 'Faible couplage = dépendances minimales, évolution indépendante des modules.' },
  { id: 'dq139', module: 'd11', q: 'Quelles sont les 2 familles d\u2019architectures réparties ?', options: ['Classiques (client/serveur, couches, P2P) et modernes (SOA, microservices, serverless, événementielle)', 'Rapides et lentes', 'Java et .NET', 'TCP et UDP'], answer: 0, explain: 'Classiques : client/serveur, en couches, Pair-à-pair. Modernes : SOA, microservices, serverless (+ événementielle).' },

  // ───── M12 — Architectures classiques ─────
  { id: 'dq140', module: 'd12', q: 'L\u2019architecture client-serveur repose sur…', options: ['Le principe d\u2019accès à des ressources centralisées via un réseau', 'Des pairs égaux', 'Des fonctions sans serveur', 'Un bus d\u2019entreprise'], answer: 0, explain: 'Deux parties distinctes : le client envoie des requêtes, le serveur traite et répond. Exemple : application desktop interrogeant une BDD sur un serveur.' },
  { id: 'dq141', module: 'd12', q: 'Dans l\u2019architecture en couches, chaque couche…', options: ['Possède une responsabilité propre et ne communique qu\u2019avec les couches voisines', 'Communique avec toutes les couches', 'Est indépendante du déploiement physique', 'Est obligatoirement sur une machine distincte'], answer: 0, explain: 'Modèle conceptuel : responsabilités propres (présentation, logique métier, accès aux données), communication avec les couches voisines uniquement.' },
  { id: 'dq142', module: 'd12', q: 'Les objectifs de l\u2019architecture en couches sont…', options: ['Modularité, maintenance, réutilisabilité, séparation des préoccupations', 'Vitesse, sécurité, coût', 'Centralisation, contrôle', 'Scalabilité maximale'], answer: 0, explain: '4 objectifs : améliorer la modularité, faciliter la maintenance, encourager la réutilisabilité, clarifier la séparation des préoccupations.' },
  { id: 'dq143', module: 'd12', q: 'L\u2019architecture 3-tiers sépare physiquement…', options: ['L\u2019interface utilisateur (presentation), la logique applicative (business logic) et les données (data)', 'TCP, IP et MAC', 'Le client, le routeur et le DNS', 'Deux pairs'], answer: 0, explain: '3-tiers : presentation tier (user interfaces) / business logic tier (application servers) / data tier (database servers). Le n-tiers ajoute des tiers (serveur Web).' },
  { id: 'dq144', module: 'd12', q: 'Dans un réseau P2P, chaque pair…', options: ['Joue simultanément le rôle de client et de serveur', 'Est uniquement serveur', 'Est uniquement client', 'Est un routeur'], answer: 0, explain: 'P2P : chaque nœud (pair) est client ET serveur ; pas de serveur central ; pairs communiquent directement et partagent ressources.' },
  { id: 'dq145', module: 'd12', q: 'Pourquoi le réseau P2P est-il dit robuste ?', options: ['Le système continue de fonctionner même si plusieurs nœuds tombent en panne', 'Il a un serveur de secours', 'Il est chiffré', 'Il est plus rapide'], answer: 0, explain: 'P2P : décentralisé, autonome, scalable, robuste — pas de point unique de défaillance.' },
  { id: 'dq146', module: 'd12', q: 'La tolérance aux pannes de l\u2019architecture client-serveur est…', options: ['Faible : si le serveur tombe, tout s\u2019arrête', 'Très élevée', 'Identique au P2P', 'Inexistante conceptuellement'], answer: 0, explain: 'Client-serveur : point unique de défaillance + surcharge possible du serveur. P2P : tolérance très élevée.' },
  { id: 'dq147', module: 'd12', q: 'La scalabilité du P2P est…', options: ['Très élevée : chaque nouveau pair ajoute des ressources', 'Limitée par le serveur', 'Moyenne', 'Nulle'], answer: 0, explain: 'Chaque nouveau pair ajoute des ressources au réseau → scalabilité très élevée.' },

  // ───── M13 — Architectures modernes ─────
  { id: 'dq148', module: 'd13', q: 'Un service (dans SOA) est…', options: ['Une unité fonctionnelle autonome, faiblement couplée, réalisant une tâche métier précise, utilisable par plusieurs applications', 'Un serveur physique', 'Une VM', 'Un conteneur Docker'], answer: 0, explain: 'SOA : fonctionnalités organisées en services indépendants, accessibles à distance via interfaces standardisées (REST, SOAP).' },
  { id: 'dq149', module: 'd13', q: 'Quel est l\u2019ordre de fonctionnement SOA ?', options: ['Le fournisseur publie le service dans le registre → le client interroge le registre → invocation et consommation', 'Le client publie → le serveur consomme', 'L\u2019ESB crée le service → le registre l\u2019exécute', 'Le registre appelle le fournisseur'], answer: 0, explain: 'Publish (fournisseur → registre), Find (client → registre), Bind/Invoke (consommation via ESB).' },
  { id: 'dq150', module: 'd13', q: 'Le rôle de l\u2019ESB dans SOA est…', options: ['Assurer le routage, la transformation et la médiation entre services', 'Stocker les données', 'Compiler le code', 'Remplacer le DNS'], answer: 0, explain: 'Enterprise Service Bus : routage, transformation, médiation entre services. Limite : il peut devenir un goulot.' },
  { id: 'dq151', module: 'd13', q: 'L\u2019architecture microservices est…', options: ['Une évolution moderne et plus fine de la SOA', 'Un remplacement du TCP/IP', 'Une architecture centralisée', 'Un protocole de transport'], answer: 0, explain: 'Microservices = évolution moderne et plus fine de la SOA (motivation : alléger la complexité centralisée autour de l\u2019ESB).' },
  { id: 'dq152', module: 'd13', q: 'Que possède chaque microservice ?', options: ['Son propre processus, son propre espace de déploiement et de données, des API légères (REST, gRPC), une capacité métier unique', 'Un serveur dédié physique', 'Sa propre JVM partagée', 'Aucune donnée'], answer: 0, explain: 'Chaque microservice : propre processus, déploiement et données ; API légères ; capacité métier unique ; développement/test/déploiement/scaling indépendants.' },
  { id: 'dq153', module: 'd13', q: 'L\u2019API Gateway est…', options: ['Le point d\u2019entrée unique pour les clients : elle reçoit les requêtes et les redirige vers les microservices appropriés', 'Une base de données', 'Le registre RMI', 'Un pare-feu matériel'], answer: 0, explain: 'API Gateway = point d\u2019entrée unique, redirection vers les bons microservices.' },
  { id: 'dq154', module: 'd13', q: 'Quel est le rôle de l\u2019orchestrateur (ex : Kubernetes) ?', options: ['Gérer automatiquement les conteneurs : déploiement, redémarrage, scaling, réseau interne', 'Écrire le code des microservices', 'Remplacer l\u2019API Gateway', 'Chiffrer les échanges'], answer: 0, explain: 'Orchestrateur = gestion automatique des conteneurs (déploiement, redémarrage, scaling, réseau interne).' },
  { id: 'dq155', module: 'd13', q: 'Dans EDA, les composants…', options: ['Réagissent à des événements ou changements d\u2019état au lieu de dépendre de requêtes directes', 'Se polluent en continu', 'Sont toujours synchrones', 'Partagent une base unique'], answer: 0, explain: 'EDA : événements publiés par des producteurs et consommés par des consommateurs via un canal/broker → communication découplée et asynchrone.' },
  { id: 'dq156', module: 'd13', q: 'Dans l\u2019exemple e-commerce du cours, le rôle de l\u2019Event Router est…', options: ['Ingestion, filtrage et poussée des événements vers les consommateurs appropriés', 'Stocker tous les événements pour toujours', 'Créer les produits', 'Remplacer le paiement'], answer: 0, explain: 'Producteurs (Retail website, Mobile app, Point-of-sale) → Event Router (ingests, filters, pushes) → Consommateurs (Warehouse Mgmt DB, Finance System, Customer Relations).' },
  { id: 'dq157', module: 'd13', q: 'Serverless signifie…', options: ['Des services cloud entièrement gérés : plus de gestion de serveurs, de configuration ni de mise à l\u2019échelle par le développeur', 'Il n\u2019y a plus de serveurs du tout', 'Des serveurs sans disque', 'Un réseau sans câbles'], answer: 0, explain: 'Serverless : le code s\u2019exécute à la demande sous forme de petites fonctions (FaaS) déclenchées par des événements ; infrastructure cloud distribuée.' },
  { id: 'dq158', module: 'd13', q: 'FaaS signifie…', options: ['Functions-as-a-Service : exécution de petites fonctions à la demande, déclenchées par des événements', 'File-as-a-Service', 'Firewall-as-a-Service', 'Format-as-a-Service'], answer: 0, explain: 'FaaS : fonctions déployées sur une infrastructure cloud distribuée, déclenchées par requête HTTP, message ou événement d\u2019un autre service.' },
  { id: 'dq159', module: 'd13', q: 'Quel type d\u2019architecture convient à l\u2019IoT et au streaming ?', options: ['L\u2019architecture événementielle', 'SOA', 'Client-serveur pur', 'En couches'], answer: 0, explain: 'Comparaison : événementielle → IoT, systèmes réactifs, streaming. Serverless → traitements ponctuels, automatisations.' },
  { id: 'dq160', module: 'd13', q: 'Dans la comparaison, la scalabilité serverless est…', options: ['Automatique, gérée par le cloud', 'Limitée par l\u2019ESB', 'Manuelle', 'Impossible'], answer: 0, explain: 'Serverless : infrastructure 100 % gérée par le cloud, scalabilité automatique, paiement à l\u2019usage.' },

  // ───── M14 — Asynchronisme ─────
  { id: 'dq161', module: 'd14', q: 'En communication asynchrone…', options: ['Les processus n\u2019attendent pas une réponse immédiate pour continuer leur exécution (découplage temporel)', 'Les processus sont bloqués en attente', 'Il n\u2019y a pas de réponse possible', 'Le réseau est plus lent'], answer: 0, explain: 'Asynchronisme : l\u2019émetteur envoie et continue ; le retour arrive plus tard via callback ou message de réponse.' },
  { id: 'dq162', module: 'd14', q: 'Que peut-il arriver à un message asynchrone ?', options: ['Il peut être stocké, transmis plus tard, ré-essayé, consommé par plusieurs acteurs', 'Il disparaît toujours', 'Il est chiffré automatiquement', 'Il devient synchrone'], answer: 0, explain: '4 possibilités : stocké, transmis plus tard, ré-essayé, consommé par plusieurs acteurs.' },
  { id: 'dq163', module: 'd14', q: 'Le producteur…', options: ['Génère un message, l\u2019envoie vers un système intermédiaire sans attendre la réponse, et continue son exécution', 'Attend le consommateur', 'Traite les messages plus tard', 'Stocke les messages durablement'], answer: 0, explain: 'Producteur : génère → envoie → continue immédiatement. Il est découplé du traitement.' },
  { id: 'dq164', module: 'd14', q: 'Le consommateur…', options: ['Reçoit le message, le traite plus tard selon sa disponibilité ; unique ou multiple', 'Émet toujours les messages', 'Doit être actif en même temps que le producteur', 'Ne peut être qu\u2019unique'], answer: 0, explain: 'Consommateur : reçoit, traite plus tard ; unique ou multiple (point-à-point ou pub/sub). Découplé dans le temps et l\u2019espace.' },
  { id: 'dq165', module: 'd14', q: 'Les rôles de l\u2019intermédiaire (broker) sont…', options: ['Stocker les messages, les acheminer, garantir la livraison, gérer les pics de charge', 'Compiler le code', 'Remplacer le routeur', 'Créer les événements'], answer: 0, explain: 'Broker : stocke, achemine, garantit la livraison, gère les pics → rend possibles découplage temporel, résilience, scalabilité.' },
  { id: 'dq166', module: 'd14', q: 'Le découplage spatial signifie…', options: ['Les acteurs n\u2019ont pas nécessairement connaissance l\u2019un de l\u2019autre', 'Les serveurs sont dans des pays différents', 'Le message voyage dans l\u2019espace', 'Les câbles sont longs'], answer: 0, explain: 'Découplage spatial = ignorance mutuelle possible ; découplage temporel = pas d\u2019obligation d\u2019agir au même moment.' },
  { id: 'dq167', module: 'd14', q: 'Comment le système gère-t-il les pics de charge ?', options: ['Il régule le flux en ralentissant, mettant en file ou rejetant proprement des messages', 'Il supprime tous les messages', 'Il double les serveurs instantanément', 'Il transforme tout en synchrone'], answer: 0, explain: 'Quand la consommation est plus lente que la production : ralentir, mettre en file, rejeter proprement.' },
  { id: 'dq168', module: 'd14', q: 'Dans le Message Passing, si le récepteur est indisponible…', options: ['Le message peut être perdu', 'Il est stocké indéfiniment', 'Le broker le retente', 'TCP le sauvegarde'], answer: 0, explain: 'Message Passing : point-à-point, destinataire unique (couplage spatial) — récepteur indisponible → message potentiellement perdu. Tech : RabbitMQ, NATS, MSMQ.' },
  { id: 'dq169', module: 'd14', q: 'Les deux types principaux de Pub/Sub sont…', options: ['Topic-based (topics nommés) et Content-based (filtres sur le contenu)', 'TCP-based et UDP-based', 'Local et distant', 'Sync et Async'], answer: 0, explain: 'Topic-based : subscribers choisissent des topics nommés. Content-based : abonnés spécifient des filtres, le routage dépend du contenu. Tech : Redis Pub/Sub, Google Pub/Sub, Apache Kafka.' },
  { id: 'dq170', module: 'd14', q: 'Dans le Queue-based Messaging, chaque message est consommé par…', options: ['Un seul destinataire', 'Tous les abonnés', 'Le producteur', 'Le routeur'], answer: 0, explain: 'Queue : message consommé par UN SEUL destinataire ; la queue = mémoire temporaire (panne) + régulation (pics).' },
  { id: 'dq171', module: 'd14', q: 'Dans le Queue-based, le sender connaît…', options: ['Juste l\u2019adresse du broker et le nom de la queue', 'L\u2019adresse IP du receiver et son état', 'Le port du consommateur', 'Rien du tout'], answer: 0, explain: 'Le sender ne connaît ni l\u2019adresse ni l\u2019état du receiver : c\u2019est le broker qui transfère au bon consommateur.' },
  { id: 'dq172', module: 'd14', q: 'Dans le streaming d\u2019événements, les événements sont stockés dans…', options: ['Un log append-only (journal en écriture seulement) distribué', 'Une base SQL', 'Un fichier par message', 'La RAM uniquement'], answer: 0, explain: 'Streaming : capture, stockage et traitement en continu ; persistance dans un journal (log) distribué append-only ; traitement temps réel ou quasi réel. Tech : Kafka Streams, Pulsar, Kinesis.' },
  { id: 'dq173', module: 'd14', q: 'Qu\u2019est-ce que le NACK ?', options: ['Un accusé indiquant un échec de traitement', 'Un accusé de réception positif', 'Un type de file', 'Un protocole de routage'], answer: 0, explain: 'ACK = confirmation de réception et traitement ; NACK = negative ACK, échec de traitement.' },
  { id: 'dq174', module: 'd14', q: 'L\u2019exponential backoff est…', options: ['Une stratégie de réessai avec attente croissante : t, 2t, 4t…', 'Un nombre fixe de tentatives', 'Un algorithme de chiffrement', 'Une file d\u2019attente prioritaire'], answer: 0, explain: 'Retry policies : simple (n tentatives fixes), exponential backoff (t, 2t, 4t…), jitter (aléa contre les pics synchrones). Après le max → Dead Letter Queue.' },
  { id: 'dq175', module: 'd14', q: 'Le partitionnement permet la scalabilité mais…', options: ['Abandonne l\u2019ordre global strict : on garantit seulement un ordre local dans chaque partition', 'Supprime la persistance', 'Double la latence', 'Empêche les ACK'], answer: 0, explain: 'Ordering + partitionnement : sous-flux parallèles = scalabilité, mais seulement un ordre local par partition.' },
  { id: 'dq176', module: 'd14', q: 'Les 3 mécanismes de durabilité des messages sont…', options: ['Messages en mémoire (volatile), persistants (disque, log append-only), redondants (dupliqués sur plusieurs nœuds)', 'Chiffrés, compressés, archivés', 'Sync, async, semi', 'TCP, UDP, QUIC'], answer: 0, explain: 'Durabilité : mémoire (volatile), persistants (non-volatile), redondants (duplication multi-nœuds pour la tolérance aux pannes).' },
  { id: 'dq177', module: 'd14', q: 'At-most-once convient quand…', options: ['La perte est tolérable mais la duplication inacceptable (ex. : notification de logs)', 'Chaque paiement doit passer', 'Les doublons sont OK', 'L\u2019ordre importe peu'], answer: 0, explain: 'At-most-once : envoi sans réessai → peut être perdu, jamais livré deux fois. Exemple : notifications de logs.' },
  { id: 'dq178', module: 'd14', q: 'Avec at-least-once, le consommateur doit être…', options: ['Idempotent (car le message peut être livré plusieurs fois)', 'Synchronisé', 'Sans état', 'Rapide'], answer: 0, explain: 'At-least-once : réémission tant que pas d\u2019ACK → livraison garantie, doublons possibles → traitement idempotent. Exemple : email de confirmation de commande.' },
  { id: 'dq179', module: 'd14', q: 'Exactly-once est…', options: ['La garantie la plus forte mais aussi la plus coûteuse (ex. : paiement, transaction bancaire)', 'La moins chère', 'Impossible à implémenter', 'Uniquement pour les logs'], answer: 0, explain: 'Exactly-once : chaque message traité une seule fois, même en cas d\u2019échec ou redémarrage — la plus forte et la plus coûteuse.' },
  { id: 'dq180', module: 'd14', q: 'Pourquoi le débogage asynchrone est-il difficile ?', options: ['Un message traverse plusieurs services de façon décalée dans le temps → il faut des outils d\u2019observabilité avancés (logs, tracing, métriques)', 'Les messages sont chiffrés', 'Il n\u2019y a pas de logs', 'Les serveurs sont lents'], answer: 0, explain: 'Débogage : parcours décalé dans le temps à travers plusieurs services → observabilité avancée nécessaire.' },
  { id: 'dq181', module: 'd14', q: 'Changer le format d\u2019un message peut…', options: ['Casser des consommateurs existants → gestion stricte des versions et compatibilité des schémas', 'Accélérer le système', 'Rien changer', 'Chiffrer les données'], answer: 0, explain: 'Évolution des messages : format modifié → consommateurs cassés si pas de gestion de versions/compatibilité.' },
  { id: 'dq182', module: 'd14', q: 'Quel problème de cohérence introduce l\u2019asynchronisme ?', options: ['Les services peuvent voir des états temporaires différents car les mises à jour ne sont pas instantanées', 'Les données disparaissent', 'Les index sont corrompus', 'Les clés primaires doublent'], answer: 0, explain: 'Cohérence : états temporaires différents entre services, car les mises à jour ne sont pas instantanées.' },
]
